package com.nthexperience.desktop;

import android.content.*;
import android.graphics.*;
import android.text.*;
import android.text.style.*;
import android.view.*;
import android.widget.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

final class XpWordPad extends XpToolPanel {
    final EditText editor;private String undo,redo;private boolean replacing;private String filename="Document.rtf";
    XpWordPad(Context c,DesktopStore store,Host host){
        super(c,store,host,"@wordpad");command("File",this::file);command("Undo",()->{if(undo!=null){String value=undo;undo=null;replace(value,true);}else say("Nothing to undo");});command("Redo",()->{if(redo!=null){String value=redo;redo=null;replace(value,false);}else say("Nothing to redo");});command("B",()->format(0));command("I",()->format(1));command("U",()->format(2));command("Font",this::font);command("Size",this::size);command("Align",this::align);command("• List",this::bullet);
        editor=new EditText(c);editor.setTextColor(Color.BLACK);editor.setBackgroundColor(Color.WHITE);editor.setGravity(Gravity.TOP|Gravity.START);editor.setTypeface(Aero.face(c));editor.setTextSize(14);editor.setPadding(dp(14),dp(10),dp(14),dp(10));editor.setContentDescription("WordPad document");editor.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_MULTI_LINE|android.text.InputType.TYPE_TEXT_FLAG_CAP_SENTENCES);editor.setFilters(new InputFilter[]{new InputFilter.LengthFilter(200000)});try{String saved=store.prefs.getString("xp_wordpad_rtf","");editor.setText(saved.isEmpty()?Html.fromHtml(store.prefs.getString("xp_wordpad_html",""),Html.FROM_HTML_MODE_LEGACY):XpRichText.parseRtf(saved));}catch(Exception invalid){editor.setText(Html.fromHtml(store.prefs.getString("xp_wordpad_html",""),Html.FROM_HTML_MODE_LEGACY));}content.addView(editor,new FrameLayout.LayoutParams(-1,-1));
        editor.addTextChangedListener(new TextWatcher(){String before;public void beforeTextChanged(CharSequence s,int a,int count,int after){before=rich();}public void onTextChanged(CharSequence s,int a,int before,int count){}public void afterTextChanged(Editable e){if(!replacing){undo=before;redo=null;}persist();}});say("Rich text • Select text, then choose formatting");
    }
    String rich(){return XpRichText.rtf(editor.getText());}
    String html(){return Html.toHtml(editor.getText(),Html.TO_HTML_PARAGRAPH_LINES_INDIVIDUAL);}
    private void persist(){store.prefs.edit().putString("xp_wordpad_html",html()).putString("xp_wordpad_rtf",rich()).apply();say(editor.length()+" characters • "+filename);}
    private void replace(String value,boolean isUndo){String current=rich();replacing=true;try{editor.setText(value.startsWith("{\\rtf")?XpRichText.parseRtf(value):Html.fromHtml(value,Html.FROM_HTML_MODE_LEGACY));}catch(Exception ignored){}replacing=false;if(isUndo)redo=current;else undo=current;persist();}
    private int[] selection(){int a=Math.max(0,editor.getSelectionStart()),b=Math.max(0,editor.getSelectionEnd());if(a==b){say("Select text to format it");return null;}return new int[]{Math.min(a,b),Math.max(a,b)};}
    private void format(int kind){int[] range=selection();if(range==null)return;undo=rich();redo=null;Editable text=editor.getText();int a=range[0],b=range[1];
        if(kind==2){UnderlineSpan[] spans=text.getSpans(a,b,UnderlineSpan.class);boolean on=spans.length==0;for(UnderlineSpan span:spans){int start=text.getSpanStart(span),end=text.getSpanEnd(span);text.removeSpan(span);if(start<a)text.setSpan(new UnderlineSpan(),start,a,Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);if(end>b)text.setSpan(new UnderlineSpan(),b,end,Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);}if(on)text.setSpan(new UnderlineSpan(),a,b,Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);}
        else{int flag=kind==0?Typeface.BOLD:Typeface.ITALIC;java.util.List<int[]> runs=new java.util.ArrayList<>();boolean all=true;for(int at=a;at<b;){int end=text.nextSpanTransition(at,b,StyleSpan.class),bits=0;for(StyleSpan span:text.getSpans(at,end,StyleSpan.class))bits|=span.getStyle();runs.add(new int[]{at,end,bits});all&=(bits&flag)!=0;at=end;}
            for(StyleSpan span:text.getSpans(a,b,StyleSpan.class)){int start=text.getSpanStart(span),end=text.getSpanEnd(span),bits=span.getStyle();text.removeSpan(span);if(start<a)text.setSpan(new StyleSpan(bits),start,a,Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);if(end>b)text.setSpan(new StyleSpan(bits),b,end,Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);}for(int[] run:runs){int bits=all?run[2]&~flag:run[2]|flag;if(bits!=0)text.setSpan(new StyleSpan(bits),run[0],run[1],Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);}}
        persist();
    }
    private void font(){String[] choices={"Tahoma","Serif","Monospace"};Aero.dialog(getContext()).setTitle("Font").setItems(choices,(d,w)->{int[] range=selection();if(range==null)return;undo=rich();redo=null;editor.getText().setSpan(new TypefaceSpan(w==0?"sans-serif":w==1?"serif":"monospace"),range[0],range[1],Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);persist();}).show();}
    private void size(){String[] sizes={"10","12","14","18","24","36","48"};Aero.dialog(getContext()).setTitle("Font size").setItems(sizes,(d,w)->{int[] r=selection();if(r==null)return;undo=rich();redo=null;for(AbsoluteSizeSpan span:editor.getText().getSpans(r[0],r[1],AbsoluteSizeSpan.class)){int start=editor.getText().getSpanStart(span),end=editor.getText().getSpanEnd(span);editor.getText().removeSpan(span);if(start<r[0])editor.getText().setSpan(new AbsoluteSizeSpan(span.getSize(),span.getDip()),start,r[0],Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);if(end>r[1])editor.getText().setSpan(new AbsoluteSizeSpan(span.getSize(),span.getDip()),r[1],end,Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);}editor.getText().setSpan(new AbsoluteSizeSpan(Integer.parseInt(sizes[w]),true),r[0],r[1],Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);persist();}).show();}
    private void align(){String[] names={"Left","Center","Right"};Aero.dialog(getContext()).setTitle("Paragraph alignment").setItems(names,(d,w)->{int a=Math.max(0,editor.getSelectionStart()),b=Math.max(a,editor.getSelectionEnd());String text=editor.getText().toString();a=text.lastIndexOf('\n',Math.max(0,a-1))+1;int end=text.indexOf('\n',b);b=end<0?text.length():end+1;if(b<=a)return;undo=rich();redo=null;for(AlignmentSpan s:editor.getText().getSpans(a,b,AlignmentSpan.class))editor.getText().removeSpan(s);editor.getText().setSpan(new AlignmentSpan.Standard(w==0?Layout.Alignment.ALIGN_NORMAL:w==1?Layout.Alignment.ALIGN_CENTER:Layout.Alignment.ALIGN_OPPOSITE),a,b,Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);persist();}).show();}
    private void bullet(){int a=Math.max(0,editor.getSelectionStart());String text=editor.getText().toString();a=text.lastIndexOf('\n',Math.max(0,a-1))+1;editor.getText().insert(a,"• ");}
    private void file(){DesktopContextMenu menu=new DesktopContextMenu(getContext(),"WordPad File menu");menu.item("New","wordpad",()->Aero.dialog(getContext()).setTitle("New document").setMessage("Save a separate file first if you want to keep this draft.").setPositiveButton("New",(d,w)->{undo=rich();redo=null;editor.setText("");filename="Document.rtf";persist();}).setNegativeButton("Cancel",null).show());menu.item("Open…","files",()->host.pick(id,"*/*"));menu.item("Save As RTF…","drive",()->host.export(id,"Document.rtf","application/rtf",XpRichText.rtf(editor.getText()).getBytes(StandardCharsets.US_ASCII)));menu.item("Save As HTML…","drive",()->host.export(id,"Document.html","text/html",html().getBytes(StandardCharsets.UTF_8)));menu.item("Save As Text…","drive",()->host.export(id,"Document.txt","text/plain",editor.getText().toString().getBytes(StandardCharsets.UTF_8)));menu.separator();menu.item("Cut","cut",()->editor.onTextContextMenuItem(android.R.id.cut));menu.item("Copy","copy",()->editor.onTextContextMenuItem(android.R.id.copy));menu.item("Paste","paste",()->editor.onTextContextMenuItem(android.R.id.paste));ContextMenus.centered(toolbar,(x,y)->ContextMenus.show(menu,toolbar,x,y));}
    @Override void importDocument(byte[] bytes,String name)throws Exception{SpannableStringBuilder text=XpRichText.read(bytes,name);undo=rich();redo=null;replacing=true;editor.setText(text);replacing=false;filename=name;persist();}
    // Edits and formatting already persist immediately. An outgoing window must
    // not overwrite preferences that a backup restore has just replaced.
}
